@@ -0,0 +1,157 @@
+// Package acceptance holds the spec's acceptance tests A1 to A9: each one
+// starts the whole server with httptest.NewServer over its own temporary
+// DataDir and drives it only through HTTP.
+package acceptance
+
+import (
+	"bytes"
+	"encoding/json"
+	"io"
+	"net/http"
+	"net/http/httptest"
+	"testing"
+
+	"git.aisoftwarefactory.world/notes/notes/internal/server"
+)
+
+// app is a running server with the cookie jar of its browser, so a session
+// set by signup or login rides along on every later call.
+type app struct {
+	t    *testing.T
+	base string
+	jar  http.CookieJar
+}
+
+// newApp builds the server over a fresh temporary DataDir and serves it on
+// a test listener, closed when the test ends.
+func newApp(t *testing.T) *app {
+	t.Helper()
+	h := server.New(server.Config{DataDir: t.TempDir()})
+	ts := httptest.NewServer(h)
+	t.Cleanup(ts.Close)
+	jar, err := cookieJar()
+	if err != nil {
+		t.Fatalf("cookie jar: %v", err)
+	}
+	return &app{t: t, base: ts.URL, jar: jar}
+}
+
+// call sends method to path (a "/..." under the test server) with the JSON
+// encoding of body when it is not nil, and answers the status and the whole
+// response body. Cookies travel in both directions.
+func (a *app) call(method, path string, body any) (int, []byte) {
+	a.t.Helper()
+	var r io.Reader
+	if body != nil {
+		data, err := json.Marshal(body)
+		if err != nil {
+			a.t.Fatalf("marshal %v: %v", body, err)
+		}
+		r = bytes.NewReader(data)
+	}
+	req, err := http.NewRequest(method, a.base+path, r)
+	if err != nil {
+		a.t.Fatalf("%s: %v", method+" "+path, err)
+	}
+	if body != nil {
+		req.Header.Set("Content-Type", "application/json")
+	}
+	res, err := a.client().Do(req)
+	if err != nil {
+		a.t.Fatalf("%s %s: %v", method, path, err)
+	}
+	defer func() { _ = res.Body.Close() }()
+	out, err := io.ReadAll(res.Body)
+	if err != nil {
+		a.t.Fatalf("read the body of %s %s: %v", method, path, err)
+	}
+	return res.StatusCode, out
+}
+
+// must expects status and decodes the body into v when v is not nil.
+func (a *app) must(status int, method, path string, body any, v any) []byte {
+	a.t.Helper()
+	got, raw := a.call(method, path, body)
+	if got != status {
+		a.t.Fatalf("%s %s answered %d, want %d: %s", method, path, got, status, raw)
+	}
+	if v != nil {
+		if err := json.Unmarshal(raw, v); err != nil {
+			a.t.Fatalf("%s %s: no JSON answer: %q: %v", method, path, raw, err)
+		}
+	}
+	return raw
+}
+
+// get asks for path without a JSON body expected.
+func (a *app) get(path string) (int, []byte) {
+	a.t.Helper()
+	return a.call(http.MethodGet, path, nil)
+}
+
+// signup logs a new account in; it fails the test unless the API answers
+// 201, and leaves the session cookie on the jar.
+func (a *app) signup(username string) {
+	a.t.Helper()
+	a.must(http.StatusCreated, http.MethodPost, "/api/signup",
+		map[string]string{"username": username, "password": "correct horse battery"}, nil)
+}
+
+// note is a note as the API answers it.
+type note struct {
+	ID        int64    `json:"id"`
+	Title     string   `json:"title"`
+	Body      string   `json:"body"`
+	Tags      []string `json:"tags"`
+	Pinned    bool     `json:"pinned"`
+	CreatedAt string   `json:"created_at"`
+	UpdatedAt string   `json:"updated_at"`
+}
+
+// notePage is one page of a listing.
+type notePage struct {
+	Notes []note `json:"notes"`
+	Total int    `json:"total"`
+	Page  int    `json:"page"`
+}
+
+// createNote posts a note and answers it as the API wrote it.
+func (a *app) createNote(title, body string, tags []string) note {
+	a.t.Helper()
+	n := note{}
+	a.must(http.StatusCreated, http.MethodPost, "/api/notes",
+		map[string]any{"title": title, "body": body, "tags": tags}, &n)
+	return n
+}
+
+func ids(ns []note) []int64 {
+	out := make([]int64, len(ns))
+	for i, n := range ns {
+		out[i] = n.ID
+	}
+	return out
+}
+
+func equalIDs(a, b []int64) bool {
+	if len(a) != len(b) {
+		return false
+	}
+	for i := range a {
+		if a[i] != b[i] {
+			return false
+		}
+	}
+	return true
+}
+
+func equalStrings(a, b []string) bool {
+	if len(a) != len(b) {
+		return false
+	}
+	for i := range a {
+		if a[i] != b[i] {
+			return false
+		}
+	}
+	return true
+}
