+package acceptance
+
+import (
+	"net/http"
+	"net/http/cookiejar"
+	"net/url"
+)
+
+// cookieJar is the browser's side of an app: it keeps the session cookie a
+// signup or login sets, and sends it back on every later call. Public so a
+// test may drop it and prove a page answers without any cookie at all.
+func cookieJar() (http.CookieJar, error) {
+	return cookiejar.New(&cookiejar.Options{PublicSuffixList: noSuffixList{}})
+}
+
+// noSuffixList treats every host as public: the test server runs on
+// 127.0.0.1, which the real list would refuse to store a cookie for.
+type noSuffixList struct{}
+
+func (noSuffixList) PublicSuffix(u *url.URL) string { return u.Host }

