+// A1: sign up, log in, GET /api/me names the user; log out, /api/me answers 401.
+func TestAuthFlow(t *testing.T) {
+	a := newApp(t)
+
+	if got, raw := a.get("/api/me"); got != http.StatusUnauthorized {
+		t.Fatalf("GET /api/me before any login answered %d, want 401: %s", got, raw)
+	}
+
+	a.signup("alice")
+
+	me := struct {
+		ID       int64  `json:"id"`
+		Username string `json:"username"`
+	}{}
+	a.must(http.StatusOK, http.MethodGet, "/api/me", nil, &me)
+	if me.Username != "alice" {
+		t.Fatalf("after signup GET /api/me named %q, want alice", me.Username)
+	}
+
+	// A fresh jar: the session signup set is gone, so login must give a new one.
+	a.client.Jar = mustJar(t)
+	if got, raw := a.get("/api/me"); got != http.StatusUnauthorized {
+		t.Fatalf("GET /api/me without the cookie answered %d, want 401: %s", got, raw)
+	}
+
+	a.must(http.StatusOK, http.MethodPost, "/api/login",
+		map[string]string{"username": "alice", "password": "correct horse battery"}, nil)
+	a.must(http.StatusOK, http.MethodGet, "/api/me", nil, &me)
+	if me.Username != "alice" {
+		t.Fatalf("after login GET /api/me named %q, want alice", me.Username)
+	}
+
+	a.must(http.StatusNoContent, http.MethodPost, "/api/logout", nil, nil)
+	if got, raw := a.get("/api/me"); got != http.StatusUnauthorized {
+		t.Fatalf("GET /api/me after logout answered %d, want 401: %s", got, raw)
+	}
+}
+
+// A2: create a note with the tags Go, go and work: the note answers
+// ["go","work"], and GET /api/tags answers go with 1 and work with 1.
+func TestTagDeduplication(t *testing.T) {
+	a := newApp(t)
+	a.signup("bob")
+
+	n := a.createNote("notes on go", "a body", []string{"Go", "go", "work"})
+	if !equalStrings(n.Tags, []string{"go", "work"}) {
+		t.Fatalf("create answered tags %v, want [go work]", n.Tags)
+	}
+
+	got := note{}
+	a.must(http.StatusOK, http.MethodGet, apiNotePath(n.ID), nil, &got)
+	if !equalStrings(got.Tags, []string{"go", "work"}) {
+		t.Fatalf("GET /api/notes/%d answered tags %v, want [go work]", n.ID, got.Tags)
+	}
+
+	tags := struct {
+		Tags []struct {
+			Tag   string `json:"tag"`
+			Count int    `json:"count"`
+		} `json:"tags"`
+	}{}
+	a.must(http.StatusOK, http.MethodGet, "/api/tags", nil, &tags)
+
+	counts := map[string]int{}
+	for _, tc := range tags.Tags {
+		counts[tc.Tag] = tc.Count
+	}
+	if counts["go"] != 1 || counts["work"] != 1 {
+		t.Fatalf("GET /api/tags answered %s, want go:1 and work:1", raw(tags.Tags))
+	}
+	if len(counts) != 2 {
+		t.Fatalf("GET /api/tags listed %d tags, want 2: %s", len(counts), raw(tags.Tags))
+	}
+}
+
+// A3: a title of 201 characters answers 400; the tag "bad tag" answers 400;
+// 11 tags answer 400.
+func TestValidation(t *testing.T) {
+	a := newApp(t)
+	a.signup("carol")
+
+	longTitle := strings.Repeat("t", 201)
+	a.expectBadRequest(longTitle, "a body", []string{"go"}, "a 201-character title")
+
+	a.expectBadRequest("a title", "a body", []string{"bad tag"}, `the tag "bad tag"`)
+
+	eleven := make([]string, 0, 11)
+	for i := range 11 {
+		eleven = append(eleven, "tag"+string(rune('a'+i)))
+	}
+	a.expectBadRequest("a title", "a body", eleven, "eleven tags")
+}
+
+// expectBadRequest posts an invalid note and expects 400.
+func (a *app) expectBadRequest(title, body string, tags []string, what string) {
+	a.t.Helper()
+	got, resp := a.call(http.MethodPost, "/api/notes",
+		map[string]any{"title": title, "body": body, "tags": tags})
+	if got != http.StatusBadRequest {
+		a.t.Fatalf("%s: POST /api/notes answered %d, want 400: %s", what, got, resp)
+	}
+}
+
+// A4: a second user's GET, PUT and DELETE of the first user's note answer
+// 404, and the note is unchanged.
+func TestOwnership(t *testing.T) {
+	dir := t.TempDir()
+
+	first := newAppIn(t, dir)
+	first.signup("dave")
+	owned := first.createNote("mine", "my own words", []string{"private"})
+
+	second := newAppIn(t, dir)
+	second.signup("erin")
+
+	if got, resp := second.get(apiNotePath(owned.ID)); got != http.StatusNotFound {
+		t.Fatalf("second user's GET /api/notes/%d answered %d, want 404: %s", owned.ID, got, resp)
+	}
+	if got, resp := second.call(http.MethodPut, apiNotePath(owned.ID),
+		map[string]any{"title": "stolen", "body": "rewritten", "tags": []string{"mine"}}); got != http.StatusNotFound {
+		t.Fatalf("second user's PUT /api/notes/%d answered %d, want 404: %s", owned.ID, got, resp)
+	}
+	if got, resp := second.call(http.MethodDelete, apiNotePath(owned.ID), nil); got != http.StatusNotFound {
+		t.Fatalf("second user's DELETE /api/notes/%d answered %d, want 404: %s", owned.ID, got, resp)
+	}
+
+	got := note{}
+	first.must(http.StatusOK, http.MethodGet, apiNotePath(owned.ID), nil, &got)
+	if got.Title != owned.Title || got.Body != owned.Body || !equalStrings(got.Tags, owned.Tags) {
+		t.Fatalf("the note changed under its owner: %+v, want %+v", got, owned)
+	}
+}
+
+// A5: with 25 notes, page 1 answers 20 notes and a total of 25, page 2
+// answers 5; after an edit of the oldest note it comes first.
+func TestPaginationAndOrder(t *testing.T) {
+	a := newApp(t)
+	a.signup("frank")
+
+	created := make([]note, 0, 25)
+	for i := range 25 {
+		created = append(created, a.createNote("note "+itoa(i), "body", nil))
+	}
+	// The store lists the most recently updated first, so the order just
+	// created is the reverse of the listing.
+	wantAll := reverse(created)
+
+	page1 := notePage{}
+	a.must(http.StatusOK, http.MethodGet, "/api/notes?page=1", nil, &page1)
+	if page1.Total != 25 {
+		t.Fatalf("page 1 answered total %d, want 25", page1.Total)
+	}
+	if len(page1.Notes) != 20 {
+		t.Fatalf("page 1 answered %d notes, want 20", len(page1.Notes))
+	}
+	if !equalIDs(ids(page1.Notes), wantAll[:20]) {
+		t.Fatalf("page 1 holds %v, want %v", ids(page1.Notes), wantAll[:20])
+	}
+
+	page2 := notePage{}
+	a.must(http.StatusOK, http.MethodGet, "/api/notes?page=2", nil, &page2)
+	if page2.Total != 25 {
+		t.Fatalf("page 2 answered total %d, want 25", page2.Total)
+	}
+	if len(page2.Notes) != 5 {
+		t.Fatalf("page 2 answered %d notes, want 5", len(page2.Notes))
+	}
+	if !equalIDs(ids(page2.Notes), wantAll[20:]) {
+		t.Fatalf("page 2 holds %v, want %v", ids(page2.Notes), wantAll[20:])
+	}
+
+	oldest := created[0]
+	a.must(http.StatusOK, http.MethodPut, apiNotePath(oldest.ID),
