+		t.Fatalf("after an edit of the oldest note, page 1 starts with %v, want it to hold %d first",
+			ids(after.Notes), oldest.ID)
+	}
+	if after.Notes[0].Title != "edited oldest" {
+		t.Fatalf("page 1 starts with %q, want the edited note", after.Notes[0].Title)
+	}
+}
