+	a := newApp(t)
+
+	if got, raw := a.get("/api/me"); got != http.StatusUnauthorized {
+		t.Fatalf("GET /api/me before any login answered %d, want 401: %s", got, raw)
+	}
+
+	a.signup("alice")
+
+	me := struct {
+		ID       int64  `json:"id"`
+		Username string `json:"username"`
+	}{}
+	a.must(http.StatusOK, http.MethodGet, "/api/me", nil, &me)
+	if me.Username != "alice" {
+		t.Fatalf("after signup GET /api/me named %q, want alice", me.Username)
+	}
+
+	// A fresh jar: the session signup set is gone, so login must give a new one.
+	a.client.Jar = mustJar(t)
+	if got, raw := a.get("/api/me"); got != http.StatusUnauthorized {
+		t.Fatalf("GET /api/me without the cookie answered %d, want 401: %s", got, raw)
+	}
+
+	a.must(http.StatusOK, http.MethodPost, "/api/login",
+		map[string]string{"username": "alice", "password": "correct horse battery"}, nil)
+	a.must(http.StatusOK, http.MethodGet, "/api/me", nil, &me)
+	if me.Username != "alice" {
+		t.Fatalf("after login GET /api/me named %q, want alice", me.Username)
+	}
+
+	a.must(http.StatusNoContent, http.MethodPost, "/api/logout", nil, nil)
+	if got, raw := a.get("/api/me"); got != http.StatusUnauthorized {
